import pubchempy as pcp
from rdkit import Chem
from rdkit.Chem import AllChem

try:
    c = pcp.get_compounds('Aspirin', 'name')
    if c:
        smiles = c[0].canonical_smiles
        print(f"SMILES for Aspirin: {smiles}")
        mol = Chem.MolFromSmiles(smiles)
        if mol:
            fp = AllChem.GetMorganFingerprintAsBitVect(mol, 2, useChirality=True)
            print("Fingerprint generated successfully")
        else:
            print("Failed to generate Mol from SMILES")
    else:
        print("Compound not found")
except Exception as e:
    print(f"Error: {e}")
